<?php $statusLabels = ['active' => 'Active', 'inactive' => 'Inactive', 'maintenance' => 'Maintenance']; ?>
<div class="page-heading"><div><div class="breadcrumb-line">Home <span>&rsaquo;</span> Bay Management <span>&rsaquo;</span> <b>All Bays</b></div><h1>Bay Management</h1><p>Manage workshop bays and assign one employee to each bay.</p></div><a href="index.php?page=admin&amp;section=bays-add" class="btn btn-primary">+ Add Bay</a></div>
<div class="row g-3 bay-summary"><div class="col-sm-6 col-xl-3"><div class="stat-card accent"><small>Total Bays</small><strong><?= count($rows) ?></strong><span>All workshop bays</span></div></div><div class="col-sm-6 col-xl-3"><div class="stat-card"><small>Available</small><strong><?= count(array_filter($rows, static fn ($row): bool => $row['status'] === 'active' && empty($row['job_card_no']))) ?></strong><span>Ready for work</span></div></div><div class="col-sm-6 col-xl-3"><div class="stat-card"><small>Occupied</small><strong><?= count(array_filter($rows, static fn ($row): bool => !empty($row['job_card_no']))) ?></strong><span>Pending or ongoing jobs</span></div></div><div class="col-sm-6 col-xl-3"><div class="stat-card red"><small>Maintenance</small><strong><?= count(array_filter($rows, static fn ($row): bool => $row['status'] === 'maintenance')) ?></strong><span>Temporarily unavailable</span></div></div></div>
<div class="admin-panel bay-list-panel"><div class="panel-heading"><h2>Workshop Bays</h2><span class="text-muted"><?= count($rows) ?> record<?= count($rows) === 1 ? '' : 's' ?></span></div><div class="table-responsive"><table class="table admin-table bay-table"><thead><tr><th>#</th><th>Bay Name / Number</th><th>Status</th><th>Current Job Card</th><th>Vehicle</th><th>Assigned Employee</th><th>Notes</th><th>Actions</th></tr></thead><tbody><?php if (!$rows): ?><tr><td colspan="8" class="empty-table">No bays found. Click Add Bay to create the first workshop bay.</td></tr><?php else: foreach ($rows as $index => $row): ?><tr><td><?= $index + 1 ?></td><td><strong><?= e($row['bay_name']) ?></strong></td><td><span class="status-badge status-<?= e($row['status']) ?>"><?= e($statusLabels[$row['status']]) ?></span></td><td><?= e($row['job_card_no'] ?: 'Available') ?><?php if ($row['job_status']): ?><small class="d-block text-muted"><?= e(ucfirst($row['job_status'])) ?></small><?php endif; ?></td><td><?= e($row['vehicle_number'] ?: '-') ?></td><td><?= e($row['employee_name'] ? $row['employee_name'] . ' (' . $row['employee_code'] . ')' : 'Not assigned') ?></td><td><?= e($row['notes'] ?: '-') ?></td><td><div class="action-links employee-actions"><a href="index.php?page=admin&amp;section=bays-edit&amp;id=<?= (int) $row['id'] ?>" title="Edit bay" aria-label="Edit bay">&#9998;</a><form method="post" action="index.php?page=admin&amp;section=bays-delete" onsubmit="return confirm('Delete this bay?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="bay_id" value="<?= (int) $row['id'] ?>"><button type="submit" title="Delete bay" aria-label="Delete bay">&#128465;</button></form></div></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
